import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Button,
  CircularProgress,
  MenuItem,
  FormControl,
  InputLabel,
  Select,
  Stack,
} from "@mui/material";
import Swal from "sweetalert2";
import { apiRequest } from "../utils/apiRequest";
import { API } from "../api/endpoints";
import TechnicianKpiTable from "../components/TechnicianKpiTable";
import { POST_ASSIGNMENT_SLA_LEVELS, parseKpiResponse } from "../utils/slaKpi";

const PRIORITIES = ["Low", "Medium", "High", "Urgent"];

const SLAManagement = () => {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [rows, setRows] = useState([]);
  const [formPriority, setFormPriority] = useState("Urgent");
  const [formMinutes, setFormMinutes] = useState("60");
  const [kpiRows, setKpiRows] = useState([]);
  const [kpiLoading, setKpiLoading] = useState(false);

  const Toast = Swal.mixin({
    toast: true,
    position: "top-end",
    showConfirmButton: false,
    timer: 1500,
    timerProgressBar: true,
    didOpen: (toast) => {
      toast.addEventListener("mouseenter", Swal.stopTimer);
      toast.addEventListener("mouseleave", Swal.resumeTimer);
    },
    customClass: {
      container: "swal-toast-container",
      popup: "swal-toast-popup",
    },
  });

  useEffect(() => {
    const styleSheet = document.createElement("style");
    styleSheet.textContent = `
      .swal-toast-container {
        z-index: 9999 !important;
      }
      .swal-toast-popup {
        font-family: 'Inter', sans-serif;
        font-size: 14px;
      }
    `;
    document.head.appendChild(styleSheet);
    return () => {
      document.head.removeChild(styleSheet);
    };
  }, []);

  const fetchSlaList = async () => {
    setLoading(true);
    try {
      const res = await apiRequest({ ...API.slaList });
      const list = res?.data ?? res;
      setRows(Array.isArray(list) ? list : []);
    } catch (e) {
      setRows([]);
      Toast.fire({
        icon: "warning",
        title: "Warning",
        text: e?.message || "Could not load SLA rules.",
      });
    } finally {
      setLoading(false);
    }
  };

  const fetchKpi = async () => {
    setKpiLoading(true);
    try {
      const res = await apiRequest({ ...API.ticketsKpi });
      setKpiRows(parseKpiResponse(res));
    } catch (e) {
      setKpiRows([]);
      Toast.fire({
        icon: "warning",
        title: "Warning",
        text: e?.message || "Could not load technician KPI data.",
      });
    } finally {
      setKpiLoading(false);
    }
  };

  useEffect(() => {
    fetchSlaList();
    fetchKpi();
  }, []);

  const applyPostAssignmentPreset = (minutes) => {
    setFormMinutes(String(minutes));
  };

  const saveRule = async (priority, resolution_time) => {
    setSaving(true);
    try {
      await apiRequest({
        ...API.slaSettingsUpdate,
        data: { priority, resolution_time: Number(resolution_time) },
      });
      Toast.fire({
        icon: "success",
        title: "Success",
        text: "SLA rule updated.",
      });
      await fetchSlaList();
    } catch (e) {
      Toast.fire({
        icon: "error",
        title: "Error",
        text: e?.message || "Failed to update SLA.",
      });
    } finally {
      setSaving(false);
    }
  };

  const runSlaCheck = async () => {
    try {
      const res = await apiRequest({ ...API.maintenanceCheckSla });
      Toast.fire({
        icon: "success",
        title: "Success",
        text: res?.message || "SLA check triggered.",
      });
    } catch (e) {
      Toast.fire({
        icon: "error",
        title: "Error",
        text: e?.message || "SLA check failed.",
      });
    }
  };

  const rowLabel = (row) =>
    row.priority ?? row.name ?? row.level ?? row.title ?? "Rule";
  const rowMinutes = (row) =>
    row.resolution_time ??
    row.resolution_minutes ??
    row.sla_minutes ??
    row.minutes ??
    "";

  return (
    <Box sx={{ py: 3, px: { xs: 1, sm: 2 }, maxWidth: 1200, mx: "auto" }}>
      <Typography variant="h5" sx={{ fontWeight: 600, mb: 1 }}>
        SLA Management
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
        Configure resolution targets by priority and review technician
        resolution KPIs. Post-assignment SLA timers start when a ticket is
        assigned.
      </Typography>

      <Paper variant="outlined" sx={{ p: 2, mb: 3 }}>
        <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 1 }}>
          Post-assignment SLA timers
        </Typography>
        <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
          Resolution clock starts at assignment. Targets by urgency level:
        </Typography>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell sx={{ fontWeight: "bold" }}>Level</TableCell>
              <TableCell sx={{ fontWeight: "bold" }}>
                Maps to priority
              </TableCell>
              <TableCell sx={{ fontWeight: "bold" }} align="right">
                Target
              </TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {POST_ASSIGNMENT_SLA_LEVELS.map((row) => (
              <TableRow key={row.level}>
                <TableCell>{row.level}</TableCell>
                <TableCell>{row.priorityKeys.slice(1).join(", ")}</TableCell>
                <TableCell align="right">{row.hoursLabel}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </Paper>

      <Paper sx={{ p: 2, mb: 3 }}>
        <Typography variant="subtitle1" sx={{ fontWeight: 600, mb: 2 }}>
          Quick update
        </Typography>
        <Stack
          direction={{ xs: "column", sm: "row" }}
          spacing={2}
          alignItems="flex-end"
        >
          <FormControl size="small" sx={{ minWidth: 140 }}>
            <InputLabel>Priority</InputLabel>
            <Select
              label="Priority"
              value={formPriority}
              onChange={(e) => setFormPriority(e.target.value)}
            >
              {PRIORITIES.map((p) => (
                <MenuItem key={p} value={p}>
                  {p}
                </MenuItem>
              ))}
            </Select>
          </FormControl>
          <TextField
            size="small"
            label="Minutes"
            type="number"
            value={formMinutes}
            onChange={(e) => setFormMinutes(e.target.value)}
            inputProps={{ min: 1 }}
          />
          <Button
            variant="contained"
            disabled={saving}
            onClick={() => saveRule(formPriority, formMinutes)}
            sx={{
              backgroundColor: "#43B02A",
              textTransform: "none",
              "&:hover": { backgroundColor: "#3A8F22" },
            }}
          >
            Save
          </Button>
          <Button
            variant="outlined"
            onClick={runSlaCheck}
            sx={{ textTransform: "none" }}
          >
            Run SLA check
          </Button>
        </Stack>
        <Stack direction="row" spacing={1} sx={{ mt: 2, flexWrap: "wrap" }}>
          {POST_ASSIGNMENT_SLA_LEVELS.map((preset) => (
            <Button
              key={preset.level}
              size="small"
              variant="outlined"
              onClick={() => applyPostAssignmentPreset(preset.minutes)}
              sx={{ textTransform: "none" }}
            >
              {preset.level} ({preset.hoursLabel})
            </Button>
          ))}
        </Stack>
      </Paper>

      <Paper sx={{ overflow: "hidden" }}>
        {loading ? (
          <Box sx={{ display: "flex", justifyContent: "center", py: 6 }}>
            <CircularProgress />
          </Box>
        ) : rows.length === 0 ? (
          <Typography sx={{ p: 3 }} color="text.secondary">
            No SLA rules returned. Use quick update to create rules.
          </Typography>
        ) : (
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>Priority</TableCell>
                <TableCell align="right">Minutes</TableCell>
                <TableCell align="right">Action</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {rows.map((row, idx) => (
                <SlaRow
                  key={row.id ?? idx}
                  label={rowLabel(row)}
                  initialMinutes={rowMinutes(row)}
                  onSave={saveRule}
                  disabled={saving}
                />
              ))}
            </TableBody>
          </Table>
        )}
      </Paper>

      <Paper sx={{ p: 2, mt: 3 }}>
        <Box
          sx={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            mb: 2,
            flexWrap: "wrap",
            gap: 1,
          }}
        >
          <Typography variant="subtitle1" sx={{ fontWeight: 600 }}>
            Technician resolution KPI
          </Typography>
          <Button
            size="small"
            variant="outlined"
            onClick={fetchKpi}
            disabled={kpiLoading}
            sx={{ textTransform: "none" }}
          >
            Refresh KPI
          </Button>
        </Box>

        <TechnicianKpiTable rows={kpiRows} loading={kpiLoading} />
      </Paper>
    </Box>
  );
};

function SlaRow({ label, initialMinutes, onSave, disabled }) {
  const [minutes, setMinutes] = useState(
    initialMinutes !== "" && initialMinutes != null
      ? String(initialMinutes)
      : "",
  );

  useEffect(() => {
    setMinutes(
      initialMinutes !== "" && initialMinutes != null
        ? String(initialMinutes)
        : "",
    );
  }, [initialMinutes, label]);

  return (
    <TableRow>
      <TableCell>{label}</TableCell>
      <TableCell align="right" sx={{ maxWidth: 120 }}>
        <TextField
          size="small"
          type="number"
          value={minutes}
          onChange={(e) => setMinutes(e.target.value)}
          inputProps={{ min: 1 }}
          fullWidth
        />
      </TableCell>
      <TableCell align="right">
        <Button
          size="small"
          variant="outlined"
          disabled={disabled}
          onClick={() => onSave(label, minutes)}
          sx={{ textTransform: "none" }}
        >
          Save
        </Button>
      </TableCell>
    </TableRow>
  );
}

export default SLAManagement;
