import React from "react";
import {
  Box,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
  Chip,
  CircularProgress,
} from "@mui/material";
import {
  formatDateTime,
  formatDurationMinutes,
  summarizeKpiRows,
} from "../utils/slaKpi";

const TechnicianKpiTable = ({ rows = [], loading = false }) => {
  const summary = summarizeKpiRows(rows);

  if (loading) {
    return (
      <Box sx={{ display: "flex", justifyContent: "center", py: 4 }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      <Box
        sx={{
          display: "grid",
          gridTemplateColumns: {
            xs: "1fr 1fr",
            sm: "repeat(4, 1fr)",
          },
          gap: 2,
          mb: 2,
        }}
      >
        {[
          { label: "Tickets", value: summary.total },
          { label: "Resolved", value: summary.resolved },
          {
            label: "Avg resolution",
            value: formatDurationMinutes(summary.avgResolutionMinutes),
          },
          { label: "SLA breached", value: summary.slaBreachedCount },
        ].map((card) => (
          <Paper
            key={card.label}
            variant="outlined"
            sx={{ p: 1.5, textAlign: "center" }}
          >
            <Typography variant="h6" sx={{ fontWeight: 700 }}>
              {card.value}
            </Typography>
            <Typography variant="caption" color="text.secondary">
              {card.label}
            </Typography>
          </Paper>
        ))}
      </Box>

      <TableContainer
        component={Paper}
        variant="outlined"
        sx={{ overflowX: "auto" }}
      >
        <Table size="small" sx={{ minWidth: 960 }}>
          <TableHead>
            <TableRow sx={{ backgroundColor: "#f5f5f5" }}>
              <TableCell sx={{ fontWeight: "bold" }}>Ticket</TableCell>
              <TableCell sx={{ fontWeight: "bold" }}>Technician</TableCell>
              <TableCell sx={{ fontWeight: "bold" }}>Priority</TableCell>
              <TableCell sx={{ fontWeight: "bold" }}>Created</TableCell>
              <TableCell sx={{ fontWeight: "bold" }}>Assigned</TableCell>
              <TableCell sx={{ fontWeight: "bold" }}>Resolved</TableCell>
              <TableCell sx={{ fontWeight: "bold" }} align="right">
                Creation → closure
              </TableCell>
              <TableCell sx={{ fontWeight: "bold" }} align="right">
                Assign → resolve
              </TableCell>
              <TableCell sx={{ fontWeight: "bold" }}>SLA</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {rows.length === 0 ? (
              <TableRow>
                <TableCell colSpan={9} align="center">
                  No KPI data available
                </TableCell>
              </TableRow>
            ) : (
              rows.map((row) => (
                <TableRow key={row.id}>
                  <TableCell>
                    #{row.id} — {row.title}
                  </TableCell>
                  <TableCell>{row.assignee}</TableCell>
                  <TableCell>{row.priority}</TableCell>
                  <TableCell>{formatDateTime(row.created_at)}</TableCell>
                  <TableCell>{formatDateTime(row.assigned_at)}</TableCell>
                  <TableCell>{formatDateTime(row.resolved_at)}</TableCell>
                  <TableCell align="right">
                    {formatDurationMinutes(
                      row.lifecycle?.totalCreationToClosureMinutes ??
                        row.resolution_minutes,
                    )}
                  </TableCell>
                  <TableCell align="right">
                    {formatDurationMinutes(
                      row.lifecycle?.assignmentToResolutionMinutes,
                    )}
                  </TableCell>
                  <TableCell>
                    {row.sla_breached || row.postAssignment?.breached ? (
                      <Chip label="Breached" size="small" color="error" />
                    ) : row.resolved_at ? (
                      <Chip label="Met" size="small" color="success" />
                    ) : (
                      <Chip label="Open" size="small" />
                    )}
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </TableContainer>
    </Box>
  );
};

export default TechnicianKpiTable;
