export const POST_ASSIGNMENT_SLA_LEVELS = [
  {
    level: "P1",
    label: "P1 — Urgent",
    priorityKeys: ["P1", "Urgent"],
    minutes: 60,
    hoursLabel: "1 hour",
  },
  {
    level: "P2",
    label: "P2 — High",
    priorityKeys: ["P2", "High"],
    minutes: 120,
    hoursLabel: "2 hours",
  },
  {
    level: "P3",
    label: "P3 — Medium",
    priorityKeys: ["P3", "Medium"],
    minutes: 240,
    hoursLabel: "4 hours",
  },
  {
    level: "P4",
    label: "P4 — Low",
    priorityKeys: ["P4", "Low"],
    minutes: 1440,
    hoursLabel: "24 hours",
  },
];

export function getSlaMinutesForPriority(priority) {
  if (!priority) return null;
  const key = String(priority).trim();
  const match = POST_ASSIGNMENT_SLA_LEVELS.find((row) =>
    row.priorityKeys.some((p) => p.toLowerCase() === key.toLowerCase()),
  );
  return match?.minutes ?? null;
}

export function getSlaLevelLabel(priority) {
  const key = String(priority || "").trim();
  const match = POST_ASSIGNMENT_SLA_LEVELS.find((row) =>
    row.priorityKeys.some((p) => p.toLowerCase() === key.toLowerCase()),
  );
  return match?.level ?? (key || "—");
}

export function formatDurationMinutes(totalMinutes) {
  if (totalMinutes == null || Number.isNaN(totalMinutes)) return "—";
  const mins = Math.round(Number(totalMinutes));
  if (mins < 60) return `${mins} min`;
  if (mins < 1440) return `${(mins / 60).toFixed(1)} hrs`;
  return `${(mins / 1440).toFixed(1)} days`;
}

export function formatDateTime(value) {
  if (!value) return "—";
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return value;
  return d.toLocaleString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
  });
}

function diffMinutes(from, to) {
  const a = new Date(from).getTime();
  const b = new Date(to).getTime();
  if (Number.isNaN(a) || Number.isNaN(b) || b < a) return null;
  return Math.round((b - a) / (1000 * 60));
}

export function computePostAssignmentSla({
  assignedAt,
  priority,
  resolvedAt,
  now = Date.now(),
}) {
  const slaMinutes = getSlaMinutesForPriority(priority);
  if (!assignedAt) {
    return {
      state: "unassigned",
      message: "SLA timer starts when the ticket is assigned.",
      slaMinutes,
      level: getSlaLevelLabel(priority),
    };
  }
  if (!slaMinutes) {
    return {
      state: "unknown",
      message: "No SLA target for this priority.",
      slaMinutes: null,
      level: getSlaLevelLabel(priority),
    };
  }

  const assignedMs = new Date(assignedAt).getTime();
  if (Number.isNaN(assignedMs)) {
    return {
      state: "unknown",
      message: "Invalid assignment time.",
      slaMinutes,
    };
  }

  const deadlineMs = assignedMs + slaMinutes * 60 * 1000;
  const endMs = resolvedAt ? new Date(resolvedAt).getTime() : now;
  const remainingMs = deadlineMs - endMs;
  const breached = remainingMs < 0;
  const resolutionMins = diffMinutes(assignedAt, resolvedAt || null);

  if (resolvedAt) {
    return {
      state: breached ? "resolved_breached" : "resolved_met",
      message: breached
        ? `Resolved after SLA deadline (${formatDurationMinutes(slaMinutes)} target).`
        : `Resolved within SLA (${formatDurationMinutes(slaMinutes)} from assignment).`,
      slaMinutes,
      level: getSlaLevelLabel(priority),
      assignedAt,
      deadlineAt: new Date(deadlineMs).toISOString(),
      resolvedAt,
      resolutionFromAssignmentMinutes: resolutionMins,
      breached,
    };
  }

  return {
    state: breached ? "active_breached" : "active",
    message: breached
      ? `SLA breached — overdue by ${formatDurationMinutes(Math.abs(remainingMs / 60000))}.`
      : `${formatDurationMinutes(remainingMs / 60000)} remaining until SLA deadline.`,
    slaMinutes,
    level: getSlaLevelLabel(priority),
    assignedAt,
    deadlineAt: new Date(deadlineMs).toISOString(),
    remainingMs,
    breached,
  };
}

export function computeCreationToClosureKpi({
  createdAt,
  assignedAt,
  resolvedAt,
  status,
}) {
  const isClosed = ["resolved", "closed"].includes(
    String(status || "").toLowerCase(),
  );
  const closureAt = resolvedAt || null;

  return {
    createdAt,
    assignedAt,
    resolvedAt: closureAt,
    totalCreationToClosureMinutes: diffMinutes(createdAt, closureAt),
    creationToAssignmentMinutes: diffMinutes(createdAt, assignedAt),
    assignmentToResolutionMinutes:
      assignedAt && closureAt ? diffMinutes(assignedAt, closureAt) : null,
    isClosed: Boolean(closureAt) || isClosed,
  };
}

export function parseKpiResponse(response) {
  const raw = response?.data ?? response;
  const list = Array.isArray(raw)
    ? raw
    : raw?.data || raw?.tickets || raw?.kpi || raw?.results || [];
  return (Array.isArray(list) ? list : []).map(normalizeKpiRow);
}

export function normalizeKpiRow(row) {
  const assignedAt =
    row.assigned_at || row.assignedAt || row.assignment_time || null;
  const resolvedAt = row.resolved_at || row.resolvedAt || row.closed_at || null;
  const createdAt = row.created_at || row.createdAt || null;

  let resolutionMinutes =
    row.total_resolution_time_minutes ??
    row.resolution_time_minutes ??
    row.resolution_minutes ??
    row.total_resolution_minutes ??
    null;

  if (resolutionMinutes == null && createdAt && resolvedAt) {
    resolutionMinutes = diffMinutes(createdAt, resolvedAt);
  }

  return {
    id: row.ticket_id ?? row.id,
    title: row.title || `Ticket #${row.ticket_id ?? row.id}`,
    priority: row.priority || "—",
    status: row.status,
    assigned_at: assignedAt,
    resolved_at: resolvedAt,
    created_at: createdAt,
    resolution_minutes: resolutionMinutes,
    assignee:
      row.assignee?.name ||
      row.assign_to?.name ||
      row.technician_name ||
      row.assignee_name ||
      "—",
    department: row.department?.name || row.department_name || "—",
    location: row.location?.name || row.location_name || "—",
    sla_breached: Boolean(row.sla_breached ?? row.breached_sla),
    postAssignment: computePostAssignmentSla({
      assignedAt,
      priority: row.priority,
      resolvedAt,
    }),
    lifecycle: computeCreationToClosureKpi({
      createdAt,
      assignedAt,
      resolvedAt,
      status: row.status,
    }),
  };
}

export function summarizeKpiRows(rows) {
  const list = Array.isArray(rows) ? rows : [];
  const withResolution = list.filter(
    (r) => r.resolution_minutes != null && !Number.isNaN(r.resolution_minutes),
  );
  const avg =
    withResolution.length > 0
      ? withResolution.reduce((s, r) => s + r.resolution_minutes, 0) /
        withResolution.length
      : null;
  const breached = list.filter(
    (r) => r.sla_breached || r.postAssignment?.breached,
  ).length;

  return {
    total: list.length,
    resolved: list.filter((r) => r.resolved_at).length,
    avgResolutionMinutes: avg,
    slaBreachedCount: breached,
  };
}
